51. 	// Mapper transforms the argument into a slice of keys to be reconciled
52. 	toRequests MapFunc
53. }
54. 
55. // Create implements EventHandler.
56. func (e *enqueueRequestsFromMapFunc) Create(ctx context.Context, evt event.CreateEvent, q workqueue.RateLimitingInterface) {
57. 	reqs := map[reconcile.Request]empty{}
58. 	e.mapAndEnqueue(ctx, q, evt.Object, reqs)
59. }
