63. 	reqs := map[reconcile.Request]empty{}
64. 	e.mapAndEnqueue(ctx, q, evt.ObjectOld, reqs)
65. 	e.mapAndEnqueue(ctx, q, evt.ObjectNew, reqs)
66. }
67. 
68. // Delete implements EventHandler.
69. func (e *enqueueRequestsFromMapFunc) Delete(ctx context.Context, evt event.DeleteEvent, q workqueue.RateLimitingInterface) {
70. 	reqs := map[reconcile.Request]empty{}
71. 	e.mapAndEnqueue(ctx, q, evt.Object, reqs)
72. }
