80. func (e *enqueueRequestsFromMapFunc) mapAndEnqueue(ctx context.Context, q workqueue.RateLimitingInterface, object client.Object, reqs map[reconcile.Request]empty) {
81. 	for _, req := range e.toRequests(ctx, object) {
82. 		_, ok := reqs[req]
